gU1(){return"\xab\u041c\u04af\u0433\u0435\u0434\u0435\u043a\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d\u0456\u04a3 \u04e9\u0437\u0456 \u043e\u0441\u044b \u0436\u0435\u0440\u0434\u0435 \u0442\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435 \u043c\u0435?"},
gU0(){return"\u0416\u043e\u049b. \u0416\u0435\u04a3\u0456\u043b\u0434\u0456\u043a\u0442\u0456\u04a3 \u04e9\u0437\u0456 \xab\u0422\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0431\u043e\u043b\u043c\u0430\u0439\u0434\u044b\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d \u0436\u043e\u0439\u043c\u0430\u0439\u0434\u044b. \u0415\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a 8.18 \u043f\u043b\u0430\u0441\u0442\u0438\u043d\u0430\u0441\u044b\u043d\u0434\u0430 \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0443\u0456 \u043c\u04af\u043c\u043a\u0456\u043d."},
gU3(){return"\u041e\u0441\u044b \u0431\u0435\u043b\u0433\u0456\u043d\u0456\u04a3 \u0430\u0441\u0442\u044b\u043d\u0430 \u043a\u04d9\u0434\u0456\u043c\u0433\u0456 \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u049b\u043e\u044f \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gU2(){return"\u0416\u043e\u049b. \u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0442\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0434\u0430, \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0434\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b."},
gU5(){return"\u0416\u043e\u043b\u0430\u0443\u0448\u044b\u043d\u044b \u0442\u04af\u0441\u0456\u0440\u0443 \u04af\u0448\u0456\u043d \u0442\u043e\u049b\u0442\u0430\u0439 \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gU4(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456 \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b, \u0431\u0456\u0440\u0430\u049b \u0442\u043e\u049b\u0442\u0430\u0442\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435\u0434\u0456. \u041e\u0442\u044b\u0440\u0493\u044b\u0437\u0443, \u0442\u04af\u0441\u0456\u0440\u0443 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0438\u0435\u0443 \u04af\u0448\u0456\u043d \u049b\u0430\u0436\u0435\u0442\u0442\u0456 \u0443\u0430\u049b\u044b\u0442 5 \u043c\u0438\u043d\u0443\u0442\u0442\u0430\u043d \u0430\u0441\u0443\u044b \u043c\u04af\u043c\u043a\u0456\u043d."},
gU7(){return"\u041a\u04d9\u0434\u0456\u043c\u0433\u0456 \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 20 \u043c\u0438\u043d\u0443\u0442\u049b\u0430 \u049b\u043e\u043d\u0434\u044b\u0440\u043c\u0430\u0439 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0438\u0435\u0443\u0441\u0456\u0437 \u049b\u0430\u043b\u0434\u044b\u0440\u0430 \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gU6(){return"\u0416\u043e\u049b. \u0411\u04b1\u043b \u0442\u04b1\u0440\u0430\u049b: \u043e\u0442\u044b\u0440\u0493\u044b\u0437\u0443\u0493\u0430, \u0442\u04af\u0441\u0456\u0440\u0443\u0433\u0435 \u043d\u0435\u043c\u0435\u0441\u0435 \u0442\u0438\u0435\u0443\u0433\u0435 \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0441\u0442\u044b \u0435\u043c\u0435\u0441 5 \u043c\u0438\u043d\u0443\u0442\u0442\u0430\u043d \u0430\u0441\u0442\u0430\u043c \u0430\u044f\u043b\u0434\u0430\u043c\u0430 (1.2-\u0442\u0430\u0440\u043c\u0430\u049b)."},
gU9(){return"\u0411\u04b1\u043b \u0442\u044b\u0439\u044b\u043c \u0436\u04d9\u0440\u0434\u0435\u043c\u0430\u049b\u044b \u0430\u043b\u0443\u0493\u0430 \u049b\u04b1\u049b\u044b\u0493\u044b \u0431\u0430\u0440 \xab\u041c\u04af\u0433\u0435\u0434\u0435\u043a\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456 \u0431\u0430\u0440 \u043a\u04e9\u043b\u0456\u043a\u043a\u0435 \u049b\u0430\u0442\u044b\u0441\u0442\u044b \u043c\u0430?"},
gU8(){return"\u0416\u043e\u049b. \u0415\u0433\u0435\u0440 \u0441\u0456\u0437\u0434\u0435 \u0442\u0435\u0433\u0456\u043d \u0430\u0432\u0442\u043e\u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0436\u04d9\u043d\u0435 \xab\u041c\u04af\u0433\u0435\u0434\u0435\u043a\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d\u0435 \u049b\u04b1\u049b\u044b\u0493\u044b\u04a3\u044b\u0437 \u0431\u043e\u043b\u0441\u0430, \u043c\u04b1\u043d\u0434\u0430\u0439 \u043c\u04af\u0433\u0435\u0434\u0435\u043a\u0442\u0435\u0440 \u043c\u0435\u043d \u043c\u04af\u0433\u0435\u0434\u0435\u043a \u0431\u0430\u043b\u0430\u043b\u0430\u0440\u0434\u044b \u0442\u0430\u0441\u044b\u043c\u0430\u043b\u0434\u0430\u0443\u0434\u044b \u049b\u043e\u0441\u0430 \u0430\u043b\u0493\u0430\u043d\u0434\u0430, \u0435\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a \u049b\u0430\u0440\u0430\u0441\u0442\u044b\u0440\u044b\u043b\u0493\u0430\u043d."},
gUb(){return"\u0422\u0430\u049b \u0436\u04d9\u043d\u0435 \u0436\u04b1\u043f \u043a\u04af\u043d\u0434\u0435\u0440\u0434\u0435\u0433\u0456 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0443 \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0440\u0456 \u0435\u043a\u0456 \u0436\u0430\u0493\u044b\u043d\u0434\u0430 \u043e\u0440\u043d\u0430\u043b\u0430\u0441\u049b\u0430\u043d. \u041c\u0435\u043d 21:00-\u0434\u0435\u043d 24:00-\u0433\u0435 \u0434\u0435\u0439\u0456\u043d \u0442\u04b1\u0440\u0430\u049b \u049b\u043e\u044f \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gUa(){return"\u0418\u04d9. \u0411\u0435\u043b\u0433\u0456\u043b\u0435\u0440\u0434\u0456\u04a3 \u0431\u04b1\u043b \u0442\u0456\u0440\u043a\u0435\u0441\u0456\u043c\u0456\u043c\u0435\u043d \u0441\u0430\u0493\u0430\u0442 21:00-\u0434\u0435\u043d 24:00-\u0433\u0435 \u0434\u0435\u0439\u0456\u043d \u0430\u0443\u044b\u0441\u0442\u044b\u0440\u0443 \u0443\u0430\u049b\u044b\u0442\u044b, \u0431\u04b1\u043b \u043a\u0435\u0437\u0434\u0435 \u0435\u043a\u0456 \u0436\u0430\u0493\u044b\u043d\u0430\u043d \u0434\u0430 \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u0440\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0435\u0434\u0456."},
gUd(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0436\u043e\u043b\u0430\u0443\u0448\u044b\u043d\u044b \u0430\u043b\u044b\u043f \u043a\u0435\u0442\u0443 \u04af\u0448\u0456\u043d 3 \u043c\u0438\u043d\u0443\u0442 \u0442\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430 \u043c\u0430?"},
gUc(){return"\u0416\u043e\u049b. \u041e\u043b \u0442\u0435\u043a \u0442\u0430\u049b \u043d\u04e9\u043c\u0456\u0440\u043b\u0435\u0440\u0433\u0435 \u0442\u04b1\u0440\u0430\u049b \u049b\u043e\u044e\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b. \u0422\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0440\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0435\u0434\u0456."},
