gUL(){return u.X},
gUK(){return"\u0416\u043e\u049b. \u0411\u0435\u043b\u0433\u0456 \u0442\u0443\u0440\u0430 \u0430\u043b\u0493\u0430, \u0441\u043e\u043b\u0493\u0430 \u0436\u04d9\u043d\u0435 \u043a\u0435\u0440\u0456 \u0431\u04b1\u0440\u044b\u043b\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435\u0434\u0456."},
gUN(){return"\u041e\u04a3 \u0436\u0430\u049b\u0442\u0430\u0493\u044b \u043a\u0435\u0434\u0435\u0440\u0433\u0456\u043d\u0456 \u0430\u0439\u043d\u0430\u043b\u044b\u043f \u04e9\u0442\u0443 \u043a\u0435\u0440\u0435\u043a \u043f\u0435?"},
